	public void unAssignWorkspace( UnAssignWorkspaceFromNotebookCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignWorkspace(command.getNotebookId());
	}
	

